<script>
(()=>{const list=document.getElementById('business-list'),tpl=document.getElementById('business-template');if(!list||!tpl)return;document.querySelector('[data-add-business]')?.addEventListener('click',()=>{const i=list.querySelectorAll('.business-allocation').length;if(i>=20){alert('A client account can have up to 20 businesses.');return}list.insertAdjacentHTML('beforeend',tpl.innerHTML.replaceAll('__INDEX__',i).replaceAll('__LETTER__',String.fromCharCode(65+i)))});list.addEventListener('click',e=>{if(e.target.matches('[data-remove-business]')){e.target.closest('.business-allocation').remove();[...list.querySelectorAll('.business-allocation')].forEach((card,i)=>{card.querySelector('legend').textContent='Business '+String.fromCharCode(65+i);card.querySelectorAll('input').forEach(input=>{input.name=input.name.replace(/businesses\[\d+\]/,`businesses[${i}]`)})})}})})();
</script>
